while let Some(c) = chars.next() {
    if c == 'o' {
        // Check if the next character is '|' to determine if it's a half note
        if chars.peek() == Some(&'|') {
            beats.push(2); // Half note
            chars.next(); // Consume the '|'
        } else {
            beats.push(4); // Whole note
        }
    } else if c == '.' {
        // Check if the next character is '|' to determine if it's a quarter note
        if chars.peek() == Some(&'|') {
            beats.push(1); // Quarter note
            chars.next(); // Consume the '|'
        }
    }
}

